<script setup>
import {ref,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {api} from '../boot/axios'
const route=useRoute(),key=ref(''),type=ref('cloud'),details=ref(null),busy=ref(false),error=ref('')
const slug=()=>String(route.params.slug||'')
async function load(){try{details.value=(await api.get('/product-updates/'+slug())).data.data}catch(e){error.value=e.response?.data?.message||'Valide sua chave para acessar.'}}
async function enter(){busy.value=true;error.value='';try{const result=(await api.post('/product-updates/access',{token:key.value,productType:type.value})).data.data;key.value='';location.assign(result.url)}catch(e){error.value=e.response?.data?.message||'Não foi possível validar a chave.'}finally{busy.value=false}}
async function download(productType){busy.value=true;error.value='';try{const result=(await api.post('/product-updates/'+slug()+'/download',{productType})).data.data;const url=new URL(result.url);if(url.origin!=='https://api.aitosoftwares.com'||!url.pathname.startsWith('/products/aitonotify/download/'))throw Error('Link inválido.');location.assign(url.href)}catch(e){error.value=e.response?.data?.message||e.message}finally{busy.value=false}}
onMounted(async()=>{const grant=new URLSearchParams(location.hash.slice(1)).get('grant');history.replaceState(null,'',location.pathname+location.search);if(grant){try{await api.post('/product-updates/'+slug()+'/redeem',{code:grant})}catch(e){error.value=e.response?.data?.message||'Link expirado.';return}}if(slug())await load()})
</script>
<template><main class="updates"><router-link to="/">AitoSoftwares</router-link><article><span>PORTAL DO COMPRADOR</span><h1>Atualizações do seu produto</h1><p>Bugfixes, melhorias e novas versões com acesso protegido pela sua chave atual.</p><p v-if="error" role="alert">{{error}}</p><template v-if="details"><h2>Olá, {{details.name}}.</h2><p>{{details.expiresAt?'Acesso válido até '+new Date(details.expiresAt).toLocaleDateString('pt-BR'):'Chave sem data de expiração.'}} Cada download verifica novamente a validade da sua chave.</p><section v-for="item in details.packages" :key="item.id"><h3>{{item.packageType==='cloud'?'Whitelabel · código fonte':'Desktop · instalador'}} · {{item.version}}</h3><p style="white-space:pre-line">{{item.notes}}</p><q-btn color="teal" no-caps label="Baixar atualização" icon="mdi-download" :loading="busy" @click="download(item.packageType||'desktop')"/></section><p v-if="!details.packages.length">Nenhum pacote publicado neste momento.</p></template><form v-else @submit.prevent="enter"><p>No Desktop, abra “Atualizações” pelo menu do aplicativo para validar a sua instalação.</p><p>Whitelabel: a chave abaixo libera downloads. Seu código funciona independentemente deste portal.</p><q-input v-model="key" outlined type="password" autocomplete="off" label="Chave de atualização do Whitelabel"/><q-btn type="submit" no-caps color="teal" label="Validar chave" :loading="busy" :disable="!key"/></form></article></main></template>
<style scoped>.updates{min-height:100vh;padding:40px 20px;background:#f1faf7;color:#12382e}.updates>a{display:block;max-width:800px;margin:auto;color:inherit}.updates article{max-width:800px;margin:35px auto;background:white;border:1px solid #cee4dc;border-radius:24px;padding:clamp(20px,5vw,50px)}h1{font-size:clamp(26px,5vw,42px);line-height:1.15;font-weight:700}h2{font-size:24px}h3{font-size:18px;line-height:1.5}p{line-height:1.7}section{border-top:1px solid #d4e8df;padding:20px 0}form .q-btn{margin-top:20px}[role=alert]{color:#a02337}</style>
